import React from 'react';
import { useSelector } from 'react-redux';

function Cart() {
  const cartItems = useSelector(state => state.cart); // Redux store'dan sepetteki ürünleri alıyoruz

  return (
    <div>
      <h2>Sepetiniz</h2>
      {cartItems.length === 0 ? (
        <p>Sepetiniz boş.</p>
      ) : (
        <div>
          {cartItems.map((product, index) => (
            <div key={index}>
              <h3>{product.name}</h3>
              <p>{product.price} TL</p>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export default Cart;
